  const hist = new Map<string, { items: Array<{ ts: number; cost: number }>; head: number; sum: number }>();
  let lastTs: number | null = null;
  const out: Array<{ allowed: boolean; remaining: number }> = [];
  for (const ev of events) {
    if (!Number.isInteger(ev.ts) || !Number.isInteger(ev.cost) || ev.cost < 0) {
      throw new Error("invalid event");
    }
    if (lastTs !== null && ev.ts < lastTs) throw new Error("timestamps must be non-decreasing");

