    const cutoff = ev.ts - window;
    while (rec.head < rec.items.length && rec.items[rec.head].ts <= cutoff) {
      rec.sum -= rec.items[rec.head].cost;
      rec.head += 1;
    }
    if (rec.head > 64 && rec.head * 2 >= rec.items.length) {
