function simulateStockReorder(initialStock, reorderPoint, targetStock, leadDays, dailyDemand) {
  if (!Number.isInteger(initialStock) || initialStock < 0) throw new Error("bad initialStock");
  if (!Number.isInteger(reorderPoint) || reorderPoint < 0) throw new Error("bad reorderPoint");

suffix:
  if (!Number.isInteger(leadDays) || leadDays < 1) throw new Error("bad leadDays");
  let stock = initialStock;
  const arrivals = new Map();
  let onOrder = 0;
  let stockoutUnits = 0;
  let ordersPlaced = 0;
  const log = [];
  for (let day = 0; day < dailyDemand.length; day += 1) {
    const d = dailyDemand[day];
    if (!Number.isInteger(d) || d < 0) throw new Error("bad demand");
    const recv = arrivals.get(day) ?? 0;
    if (recv > 0) {
      stock += recv;
      onOrder -= recv;
    }
    const sold = Math.min(stock, d);
    const missed = d - sold;
    stock -= sold;
    stockoutUnits += missed;
    let ordered = 0;
    if (stock + onOrder <= reorderPoint) {
      ordered = targetStock - (stock + onOrder);
      onOrder += ordered;
      ordersPlaced += 1;
      arrivals.set(day + leadDays, (arrivals.get(day + leadDays) ?? 0) + ordered);
    }
    log.push({ day, received: recv, sold, missed, endStock: stock, ordered });
  }
  return { endStock: stock, stockoutUnits, ordersPlaced, log };
}

